function filterByStatus(log, code) {
  return log.filter(e => e.status === code);
}
function filterByMethod(log, method) {
  return log.filter(e => e.method === method);
}
function avgResponseTime(log) {
  if (!log.length) return 0;
  return (log.reduce((a, e) => a + e.ms, 0) / log.length).toFixed(2);
}
function countByBackend(log) {
  return log.reduce((acc, e) => {
    acc[e.backend] = (acc[e.backend] || 0) + 1;
    return acc;
  }, {});
}
function renderTable(tableId, rows) {
  const tbody = document.querySelector('#' + tableId + ' tbody');
  if (!tbody) return;
  tbody.innerHTML = '';
  rows.slice(0, 50).forEach(e => {
    const tr = document.createElement('tr');
    tr.innerHTML =
      `<td>${e.id}</td><td>${e.ip}</td><td>${e.method}</td>` +
      `<td>${e.path}</td><td>${e.status}</td>` +
      `<td>${e.backend}</td><td>${e.ms} ms</td>`;
    tbody.appendChild(tr);
  });
}
function updateStats() {
  const total    = REQUEST_LOG.length;
  const ok       = filterByStatus(REQUEST_LOG, 200).length;
  const notFound = filterByStatus(REQUEST_LOG, 404).length;
  const errors   = filterByStatus(REQUEST_LOG, 502).length;
  const avg      = avgResponseTime(REQUEST_LOG);
  const byBack   = countByBackend(REQUEST_LOG);

  const el = id => document.getElementById(id);
  if (el('stat-total'))    el('stat-total').textContent    = total;
  if (el('stat-ok'))       el('stat-ok').textContent       = ok;
  if (el('stat-notfound')) el('stat-notfound').textContent = notFound;
  if (el('stat-errors'))   el('stat-errors').textContent   = errors;
  if (el('stat-avg'))      el('stat-avg').textContent      = avg + ' ms';
  if (el('stat-backends')) {
    el('stat-backends').textContent =
      Object.entries(byBack)
        .map(([b, n]) => b + ': ' + n)
        .join(' | ');
  }
}
document.addEventListener('DOMContentLoaded', () => {
  updateStats();
  renderTable('log-table', REQUEST_LOG);
  document.getElementById('btn-filter-get')?.addEventListener('click', () => {
    renderTable('log-table', filterByMethod(REQUEST_LOG, 'GET'));
  });
  document.getElementById('btn-filter-post')?.addEventListener('click', () => {
    renderTable('log-table', filterByMethod(REQUEST_LOG, 'POST'));
  });
  document.getElementById('btn-filter-all')?.addEventListener('click', () => {
    renderTable('log-table', REQUEST_LOG);
  });
});
